'use strict';
class PhotopeaBridge{
 constructor(frame){this.frame=frame;this.origin='https://www.photopea.com';this.ready=false;this.boot=null;this.pending=null;this.queue=Promise.resolve();this.handle=e=>this.receive(e);window.addEventListener('message',this.handle);}
 waitReady(){if(this.ready)return Promise.resolve();if(this.boot)return this.boot.promise;let resolve,reject;const promise=new Promise((ok,no)=>{resolve=ok;reject=no;});const timer=setTimeout(()=>{this.boot=null;reject(Error('Photopea 加载超时，请检查网络或在编辑器中点击开始使用后重试'));},90000);this.boot={promise,resolve,reject,timer};return promise;}
 receive(e){if(e.origin!==this.origin||e.source!==this.frame.contentWindow)return;if(e.data==='done'&&!this.ready){this.ready=true;if(this.boot){clearTimeout(this.boot.timer);this.boot.resolve();this.boot=null;}return;}const p=this.pending;if(!p)return;if(typeof e.data==='string'&&e.data.startsWith('GS_ERROR:'))p.error=e.data.slice(9);else if(typeof e.data==='string'&&e.data.startsWith('GS_SOURCE:'))p.source=e.data.slice(10);else if(typeof e.data==='string'&&e.data.startsWith('GS_FONT:'))p.font=e.data.slice(8);else if(e.data instanceof ArrayBuffer)p.buffer=e.data;else if(e.data==='done'){clearTimeout(p.timer);this.pending=null;if(p.error)p.reject(Error(p.error));else if(p.binary&&!p.buffer)p.reject(Error('在线编辑器没有返回文件，请重试'));else if(p.expected&&p.source!==p.expected)p.reject(Error('返回图片的标签页标识不匹配，已阻止覆盖'));else p.resolve({buffer:p.buffer,font:p.font});}}
 call(packet,{binary=false,expected=null}={}){const task=this.queue.then(async()=>{await this.waitReady();return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{this.pending=null;reject(Error('Photopea 操作超时，原图片保持不变，可重试'));},90000);this.pending={resolve,reject,timer,binary,expected};try{this.frame.contentWindow.postMessage(packet,this.origin);}catch(e){clearTimeout(timer);this.pending=null;reject(e);}});});this.queue=task.catch(()=>{});return task;}
 script(code,options){return this.call('try{'+code+'}catch(e){app.echoToOE("GS_ERROR:"+e.message);}',options);}
 dispose(){window.removeEventListener('message',this.handle);if(this.pending){clearTimeout(this.pending.timer);this.pending.reject(Error('在线编辑器已关闭'));this.pending=null;}if(this.boot){clearTimeout(this.boot.timer);this.boot.reject(Error('在线编辑器已关闭'));this.boot=null;}}
}
const PP={bridge:null,docId:null,source:null,sessions:new Map(),busy:false,serial:0};
function ppStatus(s,error=false){$('psstatus').textContent=s;$('psstatus').classList.toggle('error',error);}
function findPPScript(source){return `var found=null;for(var i=0;i<app.documents.length;i++){if(app.documents[i].source===${JSON.stringify(source)}){found=app.documents[i];break;}}if(!found)throw new Error('未找到对应图片，请重新发送当前标签页');app.activeDocument=found;`;}
async function canvasBuffer(c){const blob=await new Promise((ok,no)=>c.toBlob(b=>b?ok(b):no(Error('图片转换失败')),'image/png'));return blob.arrayBuffer();}
async function currentCanvas(){const c=cv(base.width,base.height);c.getContext('2d').drawImage(base,0,0);if(S.source){const p=await generate();c.getContext('2d').clearRect(p.r.x,p.r.y,p.r.w,p.r.h);c.getContext('2d').drawImage(p.patch,p.r.x,p.r.y);}else if(S.preview)c.getContext('2d').drawImage(S.preview.patch,S.preview.r.x,S.preview.r.y);return c;}
async function ppAction(fn){if(PP.busy)return;PP.busy=true;for(const id of ['psreturn','pspng','pspsd','pssend','psfonts','psreload'])$(id).disabled=true;try{await fn();}catch(e){ppStatus(e.message,true);}finally{PP.busy=false;for(const id of ['psreturn','pspng','pspsd','pssend','psfonts','psreload'])$(id).disabled=false;}}
async function ensurePhotopea(){if(PP.bridge)return;const frame=$('psframe');PP.bridge=new PhotopeaBridge(frame);frame.src='https://www.photopea.com/#'+encodeURIComponent(JSON.stringify({environment:{lang:'zh',theme:2,intro:false}}));ppStatus('正在加载免费 Photopea，首次加载需要联网…');await PP.bridge.waitReady();}
function ppSignature(){return JSON.stringify([currentDocument()?.version,S.source?params():null,S.nudge||null,$('pseditable').checked]);}
async function sendSelectedFont(){const font=$('font').value,asset=FontResources.get(font);if(!asset)return false;const items=asset.items||[asset];let sent=0;for(const item of items){if(item.face&&item.face.status!=='loaded')continue;const bytes=item.bytes||await item.getBytes();await PP.bridge.call(bytes.slice(0));sent++;}return !!sent;}
async function sendPhotopea(force=false){const doc=currentDocument();if(!doc)throw Error('请先打开或新建图片');PP.docId=doc.id;doc.onlinePending=true;const signature=ppSignature(),existing=PP.sessions.get(doc.id);await ensurePhotopea();if(existing&&existing.signature===signature&&!force){PP.source=existing.source;await PP.bridge.script(findPPScript(existing.source));ppStatus('已恢复该标签页在 Photopea 中的编辑状态');return;}
 const exact=await currentCanvas(),p=S.source?params():null,editable=!!(p&&p.text&&$('pseditable').checked&&$('render').value!=='glyph'&&!p.stroke&&!p.blur&&!p.angle),image=editable?cv(base.width,base.height):exact;
 if(editable){const ctx=image.getContext('2d');ctx.drawImage(base,0,0);ctx.clearRect(S.r.x,S.r.y,S.r.w,S.r.h);ctx.drawImage(await cleanBackground(p),S.r.x,S.r.y);}
 ppStatus('正在发送当前图片与所选字体…');let fontWarning='';if(p)try{await sendSelectedFont();}catch(e){fontWarning='所选字体传送失败：'+e.message;}await PP.bridge.call(await canvasBuffer(image));PP.source=doc.id+':'+doc.version+':'+(++PP.serial);
 let code=`app.activeDocument.source=${JSON.stringify(PP.source)};app.activeDocument.name=${JSON.stringify(doc.name)};`;
 if(editable){const a=fontForWeight(p.font,p.weight),display=$('font').selectedOptions?.[0]?.textContent||p.font,desired=(a?.weightRange?a.family:a?.postScriptName)||a?.family||display,baseMetric=metrics(p.font,S.source.text,p.size,p.weight),n=S.nudge||{x:0,y:0},x=S.r.x+S.a.ink.x+baseMetric.left+n.x,y=S.r.y+S.a.ink.y+baseMetric.ascent+n.y;
 code+=`var layer=app.activeDocument.artLayers.add();layer.kind=LayerKind.TEXT;layer.name='本站文字层';layer.opacity=${p.opacity*100};var t=layer.textItem;t.contents=${JSON.stringify(p.text)};t.size=${p.size};t.position=[${x},${y}];var c=new SolidColor();c.rgb.hexValue=${JSON.stringify(p.color.slice(1))};t.color=c;t.autoLeading=false;t.leading=${p.leading};t.tracking=${p.spacing*1000/p.size};var desired=${JSON.stringify(desired)},chosen=null;for(var i=0;i<app.fonts.length;i++){var f=app.fonts[i];if(f.postScriptName===desired){chosen=f;break;}if(f.family===desired||f.name===desired){if(!chosen)chosen=f;var style=String(f.style||'').toLowerCase().replace(/[ -]/g,'');if(style===${JSON.stringify(p.weight>=800?'extrabold':p.weight>=700?'bold':p.weight>=600?'semibold':p.weight>=500?'medium':p.weight<=200?'thin':p.weight<=300?'light':'regular')})chosen=f;}}if(chosen){t.font=chosen.postScriptName;app.echoToOE('GS_FONT:'+chosen.postScriptName);}else app.echoToOE('GS_FONT:未找到原候选字体，请在字体菜单核对');`;
 }
 try{const result=await PP.bridge.script(code);PP.sessions.set(doc.id,{source:PP.source,signature});ppStatus(editable?'已打开可编辑文字层。字体：'+(result.font||'请在 Photopea 中核对'):'已发送当前合成图，可用 Photopea 图层、修复和文字工具继续修改。');}
 catch(e){if(editable){PP.source+=':fallback';await PP.bridge.call(await canvasBuffer(exact));await PP.bridge.script(`app.activeDocument.source=${JSON.stringify(PP.source)};app.activeDocument.name=${JSON.stringify(doc.name)};`);PP.sessions.set(doc.id,{source:PP.source,signature});ppStatus('文字层创建失败，已保留完整合成图，可手动修改：'+e.message,true);}else throw e;}
 if(fontWarning)ppStatus($('psstatus').textContent+'；'+fontWarning,true);updatePPSuggestion();
}
function updatePPSuggestion(){if(!S.source){$('pssuggestion').textContent='可在 Photopea 字体菜单中选择免费字体，或打开自己的字体文件。';return;}const p=params(),name=$('font').selectedOptions?.[0]?.textContent||p.font;$('pssuggestion').textContent=`本站建议：${name} · ${p.size.toFixed(2)} px · 字重 ${p.weight} · 字距 ${p.spacing.toFixed(2)} px · 行距 ${p.leading.toFixed(2)} px`;} 
function openPhotopea(){if(S.busy||!S.loaded)return;PP.docId=WORK.active;$('psdialog').showModal();$('pslabel').textContent=currentDocument().name;ppAction(()=>sendPhotopea());}
async function exportPhotopea(format){if(!PP.source)throw Error('请先发送当前图片');const code=findPPScript(PP.source)+`app.echoToOE('GS_SOURCE:'+app.activeDocument.source);app.activeDocument.saveToOE(${JSON.stringify(format)});`;return (await PP.bridge.script(code,{binary:true,expected:PP.source})).buffer;}
function pngSignature(bytes){const b=new Uint8Array(bytes);return b.length>=8&&[137,80,78,71,13,10,26,10].every((v,i)=>b[i]===v);}
async function returnPhotopea(){if(WORK.active!==PP.docId)throw Error('当前标签页已变化，请先切回在线编辑的标签页');const bytes=await exportPhotopea('png');if(!pngSignature(bytes)||bytes.byteLength>80*1024*1024)throw Error('返回文件格式或大小不符合 PNG 要求');const url=URL.createObjectURL(new Blob([bytes],{type:'image/png'}));try{const im=await decodeImage(url);if(im.width*im.height>16000000)throw Error('返回图片超过 1600 万像素，请在 Photopea 中缩小图片');const prior=base.getContext('2d').getImageData(0,0,base.width,base.height);S.history.push({whole:true,data:prior,r:{x:0,y:0,w:base.width,h:base.height}});while(S.history.length>10||S.history.length>1&&S.history.reduce((n,h)=>n+h.data.data.byteLength,0)>64000000)S.history.shift();base.width=im.width;base.height=im.height;base.getContext('2d').drawImage(im,0,0);markChanged();currentDocument().onlinePending=false;clearSelection();saveDocument();PP.sessions.set(PP.docId,{source:PP.source,signature:ppSignature()});$('psdialog').close();refreshWorkspace();msg('Photopea 修改已返回原标签页，可继续识别、编辑或导出；支持撤销此次返回。');}finally{URL.revokeObjectURL(url);}}
function downloadBinary(bytes,name,type){const url=URL.createObjectURL(new Blob([bytes],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
$('photopea').onclick=$('menuphotopea').onclick=openPhotopea;$('psreturn').onclick=()=>ppAction(returnPhotopea);$('psleave').onclick=()=>{if(PP.busy)return ppStatus('正在传送图片，请等本次操作完成后切回');$('psdialog').close();};$('pssend').onclick=()=>ppAction(()=>sendPhotopea(true));$('psfonts').onclick=()=>ppAction(async()=>{if(!PP.bridge)throw Error('在线编辑器尚未就绪');const sent=await sendSelectedFont();ppStatus(sent?'已把本站所选字体送入 Photopea 字体库':'该字体没有可传送的文件，请使用 Photopea 字体菜单或从本站导入字体文件');});
for(const [id,format,ext,type] of [['pspng','png','png','image/png'],['pspsd','psd:true','psd','image/vnd.adobe.photoshop']])$(id).onclick=()=>ppAction(async()=>{const bytes=await exportPhotopea(format),doc=WORK.documents.find(d=>d.id===PP.docId);downloadBinary(bytes,(doc?.name||'Photopea').replace(/\.[^.]+$/,'')+'.'+ext,type);ppStatus('已导出 '+ext.toUpperCase());});
$('psreload').onclick=()=>ppAction(async()=>{if(PP.bridge){if(!window.confirm('确认重新加载在线编辑器？尚未返回或导出的 Photopea 修改会丢失。'))return;PP.bridge.dispose();PP.bridge=null;PP.sessions.clear();PP.source=null;}await sendPhotopea(true);});
$('psdialog').addEventListener('cancel',e=>{if(PP.busy)e.preventDefault();});
